public class FreightCalc {

    /** 偏远附加费（元）。属于新逻辑，开关关闭时不经过。 */
    private static final int REMOTE_SURCHARGE = 8;

    private final boolean remoteFeeEnabled;   // 来自现有配置

    public FreightCalc(boolean remoteFeeEnabled) {
        this.remoteFeeEnabled = remoteFeeEnabled;
    }

    public int calc(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        if (r.cod) fee += 2;
        // ↓ 对旧代码的唯一改动：一处分流。开关关闭或非目标省份时，行为与改动前逐字相同。
        if (remoteFeeEnabled && isRemoteProvince(r.province)) return calcRemoteFee(fee);
        return fee;
    }

    // ===== 新逻辑（sprout）=====

    /** 在原有运费之上叠加偏远附加费。只有 calc 里那处分流会进来。 */
    private int calcRemoteFee(int baseFee) {
        return baseFee + REMOTE_SURCHARGE;
    }

    /** 偏远省份名单。 */
    private boolean isRemoteProvince(String province) {
        return "新疆".equals(province) || "西藏".equals(province);
    }

    // ===== 以下是本练习的脚手架：原帖没给这几处的实现，为能编译与验证补的 =====

