        public RegionRule(int surcharge) {
            this.surcharge = surcharge;
        }
    }

    /** 脚手架：只放验证用到的模板 1032。 */
    private Tpl tpl(int tplId) {
        if (tplId == 1032) return new Tpl(18, 4);
