import java.util.Map;
import java.util.Set;

public class FreightCalc {

    /** 偏远地区附加费（元）。 */
    private static final int REMOTE_SURCHARGE = 8;

    /** 走新入口的省份。 */
    private static final Set<String> REMOTE_PROVINCES = Set.of("新疆", "西藏");

    private final boolean remoteFeeEnabled;   // 来自现有配置

    public FreightCalc(boolean remoteFeeEnabled) {
        this.remoteFeeEnabled = remoteFeeEnabled;
    }

    public int calc(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        if (r.cod) fee += 2;
        fee += calcRemoteFee(r.province);
        return fee;
    }

    /**
     * 新逻辑入口。开关关闭、或省份不在 {@link #REMOTE_PROVINCES} 内时返回 0，
     * 即 calc 的结果与改动前完全一致。
     */
    int calcRemoteFee(String province) {
        if (!remoteFeeEnabled) return 0;
        if (!REMOTE_PROVINCES.contains(province)) return 0;
        return REMOTE_SURCHARGE;
    }

    // ---- 以下是练习用的最小桩，真实项目里来自模板/区域数据源 ----

    public static class Req {
        public final int tplId;
        public final double weight;
        public final String province;
        public final boolean vip;
        public final boolean cod;

        public Req(int tplId, double weight, String province, boolean vip, boolean cod) {
            this.tplId = tplId;
            this.weight = weight;
            this.province = province;
            this.vip = vip;
            this.cod = cod;
        }
    }

    static class Tpl {
        final int first;
        final int next;

        Tpl(int first, int next) {
            this.first = first;
            this.next = next;
        }
    }

    static class Region {
        final int surcharge;

        Region(int surcharge) {
            this.surcharge = surcharge;
        }
    }

    private static final Map<Integer, Tpl> TPLS = Map.of(1032, new Tpl(18, 4));

    private static final Map<String, Region> REGIONS = Map.of(
            "新疆", new Region(3),
            "广东", new Region(0));

    private Tpl tpl(int tplId) {
        return TPLS.get(tplId);
    }

    private Region region(String province) {
        return REGIONS.get(province);
    }
}

